class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def solve(self, head: ListNode, value: int) -> int:
        # Traverse the linked list
        current = head
        while current:
            if current.val == value:
                return 1
            current = current.next
        return 0
